// Address Decomposition Structure
// P = Physical Address
// B = Block Size (bytes)
// S = Number of Sets
// C = Cache Capacity (bytes)

// P = [ Tag (T) | Index (I) | Offset (O) ]

O_bits = log2(B); // Block offset
I_bits = log2(S); // Set index
T_bits = Total_P_bits - I_bits - O_bits;

// Mapping Types based on Set Count (S)
// Direct Mapped (N=1): S = C / B
// N-way Set Associative: S = C / (N * B)
// Fully Associative (N=C/B): S = 1 (I_bits = 0)



// Direct Mapping Access Calculation
// L_total = Total number of cache lines

