unsigned int BlockSize; 
unsigned int NumLines = L_total;

// 1. Calculate Memory Block Number
unsigned long MBN = MemAddr / BlockSize;

// 2. Determine Cache Index (Set Index)
unsigned int Index = MBN % NumLines;

// 3. Determine Tag (for comparison)
